import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputLine = scanner.nextLine();
        String[] vals = inputLine.trim().split("\\s+");
        int[] nums = Arrays.stream(vals).mapToInt(Integer::parseInt).toArray();
        int x = Math.min(nums[0], nums[1]);
        int y = Math.max(nums[0], nums[1]);
        int product_xy = x * y;
        Map<Integer, Integer> checkMap = new HashMap<>();
        checkMap.put(1, 2 * ((1 < y % 6) && (y % 6 < 5) ? 1 : 0));
        Map<Integer, Integer> nestedMap = new HashMap<>();
        nestedMap.put(2, 4);
        nestedMap.put(3, 2);
        nestedMap.put(7, 2);
        checkMap.put(2, nestedMap.getOrDefault(y, 0));
        int result = (~1) & (product_xy - checkMap.getOrDefault(x, 0));
        System.out.println(result);
        scanner.close();
    }
}
